#!/usr/bin/env python3
"""MIRA V15: dezenter grauer Fokusverlauf und kräftige Anrufanzeige."""
from pathlib import Path
from datetime import datetime
import base64
import hashlib
import json
import shutil
import subprocess
import sys
import xml.etree.ElementTree as ET
HOME=Path.home()
SKIN=HOME/'.kodi/addons/skin.estuary.custom/xml'
BACKUPS=HOME/'.kodi/userdata/mira-backups'
LATEST=BACKUPS/'phone-style-v15-latest'
ASSETS={'mira/phone-v15-mask-350x90.png': '', 'mira/phone-v15-red-focus-720x90.png': '', 'mira/phone-v15-red-focus-350x90.png': '', 'mira/phone-v15-red-focus-500x145.png': '', 'mira/phone-v15-mask-720x90.png': '', 'mira/phone-v15-green-focus-500x145.png': '', 'mira/phone-v15-mask-500x145.png': '', 'mira/phone-v15-green-focus-720x90.png': '', 'mira/phone-v15-green-focus-350x90.png': ''}
def put(node,key,value):
    item=node.find(key)
    if item is None:item=ET.SubElement(node,key)
    item.text=str(value);return item

def patch_xml(source,expected):
    root=ET.fromstring(source)
    if root.get('id')!=('1189' if expected==4 else '1190'):raise RuntimeError('Unerwartete Fensterdefinition.')
    ids=(9612,9651,9652,9653) if expected==4 else (9660,9661)
    def background_images():
        return [ET.tostring(n) for n in root.iter('control') if n.get('type')=='image'
                and not (n.findtext('texture')=='home/mmi_icons_v1/phone.png'
                         and 'Control.HasFocus(9612)' in n.findtext('visible',''))]
    backgrounds=background_images()
    for cid in ids:
        node=root.find(".//control[@id='%d']"%cid)
        if node is None or node.get('type')!='button':raise RuntimeError('Anruf-Button fehlt: '+str(cid))
        texture=node.find('texturefocus')
        if texture is None or texture.get('colordiffuse','').upper()!='FFE4E8EC':
            raise RuntimeError('Erwarteter Buttonstand V14 fehlt: '+str(cid)+'; nichts geändert.')
        w,h=int(node.findtext('width')),int(node.findtext('height'))
        color='green' if cid in (9612,9652,9660) else 'red'
        mask='mira/phone-v15-mask-%dx%d.png'%(w,h)
        focus='mira/phone-v15-%s-focus-%dx%d.png'%(color,w,h)
        if mask not in ASSETS or focus not in ASSETS:raise RuntimeError('Unerwartete Buttongeometrie.')
        for key,text,tint in (('texturenofocus',mask,'FF15964D' if color=='green' else 'FFCE3038'),('texturefocus',focus,'FFFFFFFF')):
            item=put(node,key,text);item.attrib.clear();item.set('colordiffuse',tint)
        put(node,'textcolor','FFFFFFFF');put(node,'focusedcolor','FFFFFFFF')
        put(node,'font','font55' if expected==2 else 'font50')
        label=node.find('label')
        if label is None or not label.text:raise RuntimeError('Buttonbeschriftung fehlt.')
        label.text='[B]'+label.text.replace('[B]','').replace('[/B]','')+'[/B]'
    if expected==2:
        controls=root.find('controls');labels=controls.findall("control[@type='label']")
        if len(labels)!=3 or labels[0].findtext('label')!='Eingehender Anruf':
            raise RuntimeError('Popup-Typografie hat einen unerwarteten Stand.')
        put(labels[0],'label','[B]Eingehender Anruf[/B]')
        fields=(dict(top=205,height=110,font='font55',textcolor='FFFFFFFF'),
                dict(left=260,width=1400,top=475,height=130,font='font75',textcolor='FFFFFFFF'),
                dict(top=610,height=60,font='font45',textcolor='FFCAD3DD'))
        for label,values in zip(labels,fields):
            for key,value in values.items():put(label,key,value)
        for cid in ids:put(root.find(".//control[@id='%d']"%cid),'top',720)
    else:
        for node in root.iter('control'):
            if node.findtext('texture')=='home/mmi_icons_v1/phone.png' and 'Control.HasFocus(9612)' in node.findtext('visible',''):
                node.find('texture').set('colordiffuse','FFFFFFFF')
    if background_images()!=backgrounds:raise RuntimeError('Hintergrundprüfung fehlgeschlagen. Nichts gespeichert.')
    ET.indent(root,space='    ')
    return ET.tostring(root,encoding='utf-8',xml_declaration=True)

def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None

def reload():subprocess.run(['kodi-send','--action=ReloadSkin()'],check=False)

def install():
    changes={SKIN/'custom_MiraPhone.xml':patch_xml((SKIN/'custom_MiraPhone.xml').read_bytes(),4),
             SKIN/'custom_MiraPhoneIncoming.xml':patch_xml((SKIN/'custom_MiraPhoneIncoming.xml').read_bytes(),2)}
    for relative,encoded in ASSETS.items():
        path=SKIN.parent/'media'/relative
        if path.exists():raise RuntimeError('Neue Buttontextur existiert bereits: '+str(path))
        data=base64.b64decode(encoded,validate=True)
        if not data.startswith(b'\x89PNG\r\n\x1a\n'):raise RuntimeError('Ungültige Grafik.')
        changes[path]=data
    folder=BACKUPS/('phone-style-v15-'+datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
    folder.mkdir(parents=True,mode=0o700);records=[]
    for i,(path,data) in enumerate(changes.items()):
        before=digest(path);saved=str(i)+'.bak'
        if before is not None:shutil.copy2(path,folder/saved)
        records.append(dict(path=str(path),before=before,backup=saved,after=hashlib.sha256(data).hexdigest()))
    (folder/'manifest.json').write_text(json.dumps(records,indent=2))
    try:
        for path,data in changes.items():
            path.parent.mkdir(parents=True,exist_ok=True)
            temp=path.with_suffix('.v15.tmp');temp.write_bytes(data);temp.replace(path)
    except Exception:
        for item in records:
            path=Path(item['path'])
            if item['before'] is None:path.unlink(missing_ok=True)
            else:shutil.copy2(folder/item['backup'],path)
        raise
    LATEST.unlink(missing_ok=True);LATEST.symlink_to(folder.name)
    reload();print('V15 installiert: grauer Fokusverlauf, weiße Schrift und überarbeitete Popup-Anordnung.')
    print('Backup: '+str(folder));print('Transparenz, Hintergrund und Telefonlogik bleiben erhalten.')

def rollback():
    folder=LATEST.resolve(strict=True);records=json.loads((folder/'manifest.json').read_text())
    for item in records:
        if digest(Path(item['path']))!=item['after']:raise RuntimeError('Datei inzwischen geändert: '+item['path'])
    for item in records:
        path=Path(item['path'])
        if item['before'] is None:path.unlink(missing_ok=True)
        else:shutil.copy2(folder/item['backup'],path)
    reload();print('V15 zurückgenommen. Vorheriger V14-Stand wieder aktiv.')

def backup_git():
    repo=HOME/'rpi-automotive-setup'
    def git(*args):return subprocess.run(['git','-C',str(repo),*args],check=True,capture_output=True,text=True)
    if git('branch','--show-current').stdout.strip()!='main':raise RuntimeError('Nicht auf main.')
    git('fetch','origin');git('merge-base','--is-ancestor','origin/main','HEAD')
    mappings=[(SKIN/name,'mira/skin.estuary.custom/xml/'+name) for name in ('custom_MiraPhone.xml','custom_MiraPhoneIncoming.xml')]
    mappings += [(SKIN.parent/'media'/relative,'mira/skin.estuary.custom/media/'+relative) for relative in ASSETS]
    mappings += [(Path(__file__).resolve(),'tools/mira_phone_style_v15.py')]
    paths=[r for s,r in mappings];status=git('status','--porcelain','--',*paths).stdout
    if status.strip():raise RuntimeError('Exportziele haben lokale Änderungen:\n'+status)
    for source,relative in mappings:
        target=repo/relative;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,target)
    git('add','--',*paths)
    result=subprocess.run(['git','-C',str(repo),'diff','--cached','--quiet','--',*paths])
    if result.returncode==1:print(git('commit','--only','-m','MIRA: Grauer Buttonfokus und zentrierte Anrufanzeige','--',*paths).stdout)
    elif result.returncode:raise RuntimeError('Git-Diff fehlgeschlagen.')
    result=git('push','origin','main');print(result.stdout+result.stderr);print('GitHub-Sicherung abgeschlossen.')

if __name__=='__main__':
    try:
        if len(sys.argv)==1:install()
        elif sys.argv[1:]==['--rollback']:rollback()
        elif sys.argv[1:]==['--backup-git']:backup_git()
        else:raise RuntimeError('Optionen: --rollback oder --backup-git')
    except Exception as error:raise SystemExit('Abgebrochen: '+str(error))
